            id: id,
            sessionId: sessionId,
            matchNumber: matchNumber,
            gameType: gameType,
            raceTo: raceTo,
            opponent: opponent,
            partner: partner,
            teamMode: teamMode,
            winner: winner,
            result: result,
            startTime: startTime,
            endTime: endTime,
            matchObjective: matchObjective,
            notes: notes,
            createdAt: createdAt,
